import os

search_roots = ['/tmp', '/mnt', '/opt', '/srv', '/home', os.getcwd()]
sh_files, kv_dirs = [], []

for root in search_roots:
    if not os.path.isdir(root):
        continue
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in ('.cache', '.git', 'node_modules', '__pycache__')]
        for name in filenames:
            if name.endswith(('.sh', '.bash')):
                sh_files.append(os.path.join(dirpath, name))
        for d in dirnames:
            if any(k in d.lower() for k in ('kv', 'replicat', 'raft', 'consensus', 'cluster')):
                kv_dirs.append(os.path.join(dirpath, d))

print("Shell scripts found:")
for s in sorted(sh_files)[:50]:
    print(" -", s)
print(f"  (total: {len(sh_files)})")

print("\nService-like directories found:")
for d in sorted(kv_dirs)[:50]:
    print(" -", d)
print(f"  (total: {len(kv_dirs)})")

print("\nCWD:", os.getcwd())
print("CWD contents:", sorted(os.listdir(os.getcwd()))[:50])
