import urllib.request, json

def attempt(method, path, payload=None):
    url = f"http://127.0.0.1:8080{path}"
    data = json.dumps(payload).encode() if payload is not None else None
    req = urllib.request.Request(url, data=data, method=method)
    if data:
        req.add_header('Content-Type', 'application/json')
    try:
        with urllib.request.urlopen(req, timeout=4) as r:
            return r.status, r.read(600).decode('utf-8', 'replace')
    except Exception as ex:
        return type(ex).__name__, str(ex)

# Try the three requested puts against plausible KV endpoints
for ep in ('/kv', '/v1/kv', '/keys', '/'):
    for k, v in (('alpha', '100'), ('beta', '200'), ('gamma', '300')):
        m, body = attempt('PUT', f"{ep}/{k}", {'value': v})
        print(f"PUT {ep}/{k} = {v}  ->  {m}: {body[:120]}")
    print()
